<template>
  <!-- 搜索页面 - 全站搜索结果展示 -->
  <div class="search-view">
    <!-- 页面头部区域 -->
    <section class="page-header">
      <div class="header-content">
        <h1 class="page-title">搜索结果</h1>
      </div>
    </section>

    <div class="search-container">
      <!-- 搜索框区域 -->
      <div class="search-box-wrapper">
        <div class="search-box">
          <svg width="20" height="20" viewBox="0 0 20 20" fill="none" class="search-icon">
            <circle cx="9" cy="9" r="7" stroke="#8B2500" stroke-width="1.5" />
            <path d="M14 14l4 4" stroke="#8B2500" stroke-width="1.5" stroke-linecap="round" />
          </svg>
          <input
            v-model="searchQuery"
            type="text"
            placeholder="搜索非遗项目、传承人、资讯、视频、商品..."
            @keyup.enter="performSearch"
          />
          <button class="search-btn" @click="performSearch">搜索</button>
        </div>
      </div>

      <!-- 筛选类型标签 -->
      <div class="type-filters">
        <button
          v-for="type in searchTypes"
          :key="type.value"
          class="type-btn"
          :class="{ active: currentType === type.value }"
          @click="setType(type.value)"
        >
          {{ type.label }}
          <span v-if="getResultCount(type.value) > 0" class="type-count">
            {{ getResultCount(type.value) }}
          </span>
        </button>
      </div>

      <!-- 加载状态 -->
      <LoadingSpinner v-if="loading" />

      <!-- 空搜索状态 - 显示热门搜索词 -->
      <div v-else-if="!hasSearched" class="empty-search">
        <div class="hot-search">
          <h3>热门搜索</h3>
          <div class="hot-tags">
            <span
              v-for="word in hotSearchWords"
              :key="word"
              class="hot-tag"
              @click="quickSearch(word)"
            >
              {{ word }}
            </span>
          </div>
        </div>
        <div class="search-tips">
          <h3>搜索提示</h3>
          <ul>
            <li>输入关键词搜索非遗项目、传承人、资讯等内容</li>
            <li>可通过上方筛选按钮限定搜索范围</li>
            <li>支持按名称、地区、分类等关键词搜索</li>
          </ul>
        </div>
      </div>

      <!-- 无结果状态 -->
      <EmptyState
        v-else-if="hasSearched && !currentResults.length"
        title="没有找到相关结果"
        :description="`未找到与「${lastQuery}」相关的内容，换个关键词试试吧`"
      />

      <!-- 搜索结果列表 -->
      <div v-else class="results-section">
        <p class="results-summary">
          找到 <strong>{{ currentResults.length }}</strong> 条与「<strong>{{ lastQuery }}</strong>」相关的结果
        </p>
        <TransitionGroup name="results" tag="div" class="results-list">
          <!-- 非遗项目结果 -->
          <template v-if="currentType === 'all' || currentType === 'heritage'">
            <HeritageCard
              v-for="item in filterByType('heritage')"
              :key="'h-' + item.id"
              :heritage="item"
              @click="goToDetail('heritage', item.id)"
            />
          </template>
          <!-- 传承人结果 -->
          <template v-if="currentType === 'all' || currentType === 'inheritors'">
            <InheritorCard
              v-for="item in filterByType('inheritors')"
              :key="'i-' + item.id"
              :inheritor="item"
              @click="goToDetail('inheritors', item.id)"
            />
          </template>
          <!-- 资讯结果 -->
          <template v-if="currentType === 'all' || currentType === 'news'">
            <NewsCard
              v-for="item in filterByType('news')"
              :key="'n-' + item.id"
              :news="item"
              layout="list"
              @click="goToDetail('news', item.id)"
            />
          </template>
          <!-- 视频结果 -->
          <template v-if="currentType === 'all' || currentType === 'videos'">
            <VideoCard
              v-for="item in filterByType('videos')"
              :key="'v-' + item.id"
              :video="item"
              @click="goToDetail('videos', item.id)"
            />
          </template>
          <!-- 商品结果 -->
          <template v-if="currentType === 'all' || currentType === 'shop'">
            <ProductCard
              v-for="item in filterByType('shop')"
              :key="'p-' + item.id"
              :product="item"
              @click="goToDetail('shop', item.id)"
            />
          </template>
        </TransitionGroup>
      </div>
    </div>
  </div>
</template>

<script setup>
/**
 * SearchView.vue - 搜索页面
 *
 * 功能说明：
 * - 全站搜索结果展示，支持多种类型筛选
 * - 顶部大搜索框，支持回车和按钮触发搜索
 * - 筛选类型：全部/非遗项目/传承人/资讯/视频/商品
 * - 显示各类结果数量标签
 * - 空搜索状态显示热门搜索词和搜索提示
 * - 无结果状态显示 EmptyState
 * - 根据类型显示不同卡片组件
 */
import { ref, computed, onMounted, watch } from 'vue'
import { useStore } from 'vuex'
import { useRoute, useRouter } from 'vue-router'
import HeritageCard from '@/components/HeritageCard.vue'
import InheritorCard from '@/components/InheritorCard.vue'
import NewsCard from '@/components/NewsCard.vue'
import VideoCard from '@/components/VideoCard.vue'
import ProductCard from '@/components/ProductCard.vue'
import LoadingSpinner from '@/components/LoadingSpinner.vue'
import EmptyState from '@/components/EmptyState.vue'

// 获取 Vuex store 和 router 实例
const store = useStore()
const route = useRoute()
const router = useRouter()

// ==================== 响应式状态 ====================

/** 搜索关键词 */
const searchQuery = ref('')
/** 最后一次搜索的关键词 */
const lastQuery = ref('')
/** 当前筛选类型 */
const currentType = ref('all')
/** 是否已经执行过搜索 */
const hasSearched = ref(false)

// ==================== 搜索类型配置 ====================

/** 搜索类型选项 */
const searchTypes = [
  { label: '全部', value: 'all' },
  { label: '非遗项目', value: 'heritage' },
  { label: '传承人', value: 'inheritors' },
  { label: '资讯', value: 'news' },
  { label: '视频', value: 'videos' },
  { label: '商品', value: 'shop' }
]

/** 热门搜索词 */
const hotSearchWords = ['汉绣', '编钟', '武当武术', '黄梅挑花', '楚式漆器', '皮影戏', '传承人', '武汉']

// ==================== 计算属性 ====================

/** 从 Vuex store 获取加载状态 */
const loading = computed(() => store.state.loading)

/** 从 Vuex store 获取搜索结果 */
const searchResults = computed(() => store.state.searchResults || {})

/** 当前筛选类型下的结果列表 */
const currentResults = computed(() => {
  if (currentType.value === 'all') {
    // 合并所有类型的结果
    const all = []
    const types = ['heritage', 'inheritors', 'news', 'videos', 'shop']
    types.forEach(type => {
      const items = searchResults.value[type] || []
      items.forEach(item => {
        all.push({ ...item, _resultType: type })
      })
    })
    return all
  }
  return searchResults.value[currentType.value] || []
})

// ==================== 方法 ====================

/**
 * 获取指定类型的结果数量
 * @param {string} type - 类型值
 * @returns {number} 结果数量
 */
const getResultCount = (type) => {
  if (type === 'all') {
    let count = 0
    ;['heritage', 'inheritors', 'news', 'videos', 'shop'].forEach(t => {
      count += (searchResults.value[t] || []).length
    })
    return count
  }
  return (searchResults.value[type] || []).length
}

/**
 * 按类型筛选结果
 * @param {string} type - 类型值
 * @returns {Array} 筛选后的结果
 */
const filterByType = (type) => {
  const items = searchResults.value[type] || []
  return items.map(item => ({ ...item, _resultType: type }))
}

/**
 * 设置当前搜索类型
 * @param {string} value - 类型值
 */
const setType = (value) => {
  currentType.value = value
}

/**
 * 执行搜索
 */
const performSearch = async () => {
  const query = searchQuery.value.trim()
  if (!query) return
  lastQuery.value = query
  hasSearched.value = true
  currentPage.value = 1
  try {
    await store.dispatch('search', { q: query, type: currentType.value })
  } catch (err) {
    console.error('搜索失败:', err)
  }
}

/**
 * 快速搜索热门关键词
 * @param {string} word - 关键词
 */
const quickSearch = (word) => {
  searchQuery.value = word
  performSearch()
}

/**
 * 跳转到详情页
 * @param {string} type - 资源类型
 * @param {string} id - 资源ID
 */
const goToDetail = (type, id) => {
  const routes = {
    heritage: '/heritage',
    inheritors: '/inheritors',
    news: '/news',
    videos: '/videos',
    shop: '/shop'
  }
  router.push(`${routes[type]}/${id}`)
}

// ==================== 监听路由参数 ====================

onMounted(() => {
  // 如果 URL 中有搜索参数，自动执行搜索
  const q = route.query.q
  const type = route.query.type
  if (q) {
    searchQuery.value = q
    if (type) currentType.value = type
    performSearch()
  }
})

// 监听搜索类型变化，重新搜索
watch(currentType, () => {
  if (hasSearched.value && lastQuery.value) {
    performSearch()
  }
})
</script>

