<script setup>
/**
 * VideoCard.vue - 视频卡片
 * 
 * 展示内容:
 * - 视频封面
 * - 视频标题
 * - 视频时长
 * - 播放量
 * 
 * Props:
 * - video: object - 视频数据对象
 *   { id, title, cover, duration, views, category }
 */

defineProps({
  video: {
    type: Object,
    required: true
  }
})

// 格式化播放量
const formatViews = (views) => {
  if (!views) return '0 播放'
  if (views >= 10000) {
    return (views / 10000).toFixed(1) + '万 播放'
  }
  return views + ' 播放'
}
</script>

<template>
  <div class="video-card" v-if="video">
    <!-- 封面区域 -->
    <div class="cover-wrapper">
      <img
        :src="video.cover || '/images/video-placeholder.jpg'"
        :alt="video.title"
        class="cover-image"
        loading="lazy"
      />
      <!-- 时长标签 -->
      <span class="duration-badge" v-if="video.duration">
        {{ video.duration }}
      </span>
      <!-- 播放量 -->
      <span class="views-badge">
        ▶ {{ formatViews(video.views) }}
      </span>
      <!-- 播放按钮遮罩 -->
      <div class="cover-overlay">
        <div class="play-button">
          <span class="play-triangle">▶</span>
        </div>
      </div>
    </div>

    <!-- 标题 -->
    <div class="card-body">
      <h3 class="video-title">{{ video.title }}</h3>
      <span v-if="video.category" class="video-category">{{ video.category }}</span>
    </div>
  </div>
</template>

